from jsonb_to_recordset($json$[{"id":"che-pe-201","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the first two halogens, the more negative electron gain enthalpy belongs to","options":["fluorine","chlorine","neon","sodium"],"answer_index":1,"explanation":"Cl is more exothermic than F, a well-known exception to the simple down-group trend.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-202","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The second electron gain enthalpy of an atom is always","options":["more negative than the first","positive","zero","equal to the first"],"answer_index":1,"explanation":"A negative ion must accept another electron, so energy is required and ΔegH₂ > 0.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-203","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Conversion of O⁻(g) to O²⁻(g) is endothermic because a negative ion must","options":["lose two protons","accept another electron against its own charge","enter the 1s shell","become a cation"],"answer_index":1,"explanation":"Electron–electron repulsion in O⁻ makes the second attachment unfavourable; oxides form in the lattice, not as free O²⁻(g).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-204","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electron affinity is often quoted as the negative of the","options":["ionisation enthalpy","electron gain enthalpy","electronegativity","atomic radius"],"answer_index":1,"explanation":"Many older tables list EA as a positive number equal to −ΔegH when attachment is exothermic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-205","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine has a less negative electron gain enthalpy than chlorine because the compact 2p cloud of F suffers","options":["almost no inter-electronic repulsion","strong electron–electron repulsion when an extra electron is added","a vacant 3d subshell","lanthanoid contraction"],"answer_index":1,"explanation":"The incoming electron is forced into a very small 2p orbital already crowded with electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-206","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among F, Cl, Br and I, the most negative electron gain enthalpy belongs to","options":["fluorine","chlorine","bromine","iodine"],"answer_index":1,"explanation":"Chlorine combines a high Zeff with a large enough 3p orbital to avoid the extreme repulsion seen in F.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-207","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen has a near-zero or slightly positive electron gain enthalpy because its 2p subshell is already","options":["empty","half filled","completely filled","a d subshell"],"answer_index":1,"explanation":"Adding an electron to 2p³ forces pairing and destroys the half-filled stability, so attachment is unfavourable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-208","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium and magnesium have unfavourable (near-zero or positive) electron gain enthalpies because they possess","options":["half-filled 2p sets","filled ns² subshells","incomplete 1s shells","seven valence electrons"],"answer_index":1,"explanation":"The extra electron would have to enter a higher np orbital against a closed s pair.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-209","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among carbon, nitrogen, oxygen and fluorine, the most negative electron gain enthalpy is that of","options":["carbon","nitrogen","oxygen","fluorine"],"answer_index":3,"explanation":"Fluorine is one electron short of neon and, despite the F/Cl anomaly, is still the most exothermic of this period-2 set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-210","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Chlorine outruns fluorine in electron gain enthalpy because the incoming electron enters a larger 3p orbital with less repulsion, even though fluorine has the","options":["lower electronegativity","higher electronegativity and higher Zeff","greater number of shells","smaller nuclear charge"],"answer_index":1,"explanation":"Two trends compete: F is smaller and more electronegative, yet inter-electronic repulsion in the compact 2p cloud makes ΔegH(F) less negative than ΔegH(Cl).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-211","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity is the tendency of an atom in a chemical bond to attract the","options":["nucleus of the other atom","shared electron pair towards itself","entire molecule into the lattice","neutrons of the partner"],"answer_index":1,"explanation":"It is a bonded-atom property, not an isolated-atom energy.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-212","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The most widely used numerical scale of electronegativity is the","options":["Mulliken scale only","Pauling scale","Celsius scale","Rydberg scale"],"answer_index":1,"explanation":"Pauling assigned fluorine the value 4.0 and built the rest of the scale from bond-energy data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-213","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is the most electronegative element, with a Pauling value of about","options":["1.0","2.1","3.0","4.0"],"answer_index":3,"explanation":"χ(F) = 4.0 is the reference maximum on the Pauling scale.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-214","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity of representative elements generally increases from left to right across a","options":["group","period","lanthanoid row only","set of isotopes"],"answer_index":1,"explanation":"Zeff rises and size falls, so the bonded atom pulls the shared pair more strongly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-215","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity of representative elements generally decreases from top to bottom in a","options":["period","group","isoelectronic anion pair","triad of identical mass"],"answer_index":1,"explanation":"The bonding electrons are farther from the nucleus in the heavier congener.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-216","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the alkali metals, the member with a particularly low electronegativity is","options":["lithium","sodium","caesium","beryllium"],"answer_index":2,"explanation":"Cs is large and weakly attracting; it is one of the most electropositive metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-217","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity is a bonding property of an atom in a molecule, not an isolated-atom energy like","options":["atomic number","ionisation enthalpy","mass number","neutron count"],"answer_index":1,"explanation":"IE and electron gain enthalpy refer to gaseous atoms or ions; χ is defined for an atom already in a bond.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-218","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A large electronegativity difference between two bonded atoms favours","options":["pure covalent character","ionic character","metallic bonding only","no bond at all"],"answer_index":1,"explanation":"The shared pair is strongly displaced toward the more electronegative atom, approaching ion formation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-219","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"After fluorine, the next most electronegative element is","options":["chlorine","oxygen","nitrogen","neon"],"answer_index":1,"explanation":"Pauling values: F (4.0) > O (3.5) > N ≈ Cl (about 3.0).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-220","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metals are characterised by low electronegativity values compared with","options":["noble-gas cores","non-metals","their own cations only","neutrons"],"answer_index":1,"explanation":"Low χ and low IE together describe the electropositive, electron-losing behaviour of metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-221","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity falls in the order N > P > As because","options":["atomic size increases down group 15","nuclear charge falls down the group","they become alkali metals","the number of valence electrons decreases"],"answer_index":0,"explanation":"The bonded pair is held farther from the nucleus in the larger P and As atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-222","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In period 2 the electronegativity order is","options":["F < O < N < C","C < N < O < F","N < C < F < O","O < C < N < F"],"answer_index":1,"explanation":"χ rises steadily across the period as Zeff increases and radius falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-223","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is more electronegative than chlorine, bromine and iodine because of its","options":["larger size and lower Zeff","small size and high effective nuclear charge","half-filled 3d subshell","metallic character"],"answer_index":1,"explanation":"The shared pair in an F–X bond sits closest to a compact, highly charged fluorine atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-224","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On the Mulliken scale, electronegativity is taken as the average of","options":["atomic radius and density","ionisation enthalpy and electron gain enthalpy (in suitable units)","mass number and atomic number","melting point and boiling point"],"answer_index":1,"explanation":"Mulliken wrote χ ∝ (IE + EA)/2, combining the two isolated-atom energies that measure electron holding and accepting.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-225","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The H–F bond is more polar than the H–Cl bond because fluorine is","options":["less electronegative than chlorine","more electronegative than chlorine","larger than chlorine","a metal"],"answer_index":1,"explanation":"The greater χ(F) − χ(H) gap displaces the shared pair more strongly toward fluorine.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
